def tri(n):
    s = ''
    while n > 0:
        s += str(n % 3)
        n //= 3
    return s[::-1]

for n in range(1, 1000):
    s = tri(n)
    if n % 3 == 0:
        s += s[-2:]
    else:
        s += tri(n % 3 * 5)
    r = int(s, 3)
    if r >= 290:
        print(n)
        break

